/** Pre-rendered still of a 3D product scene (generated by scripts/render-products.mjs). */
export function Render({ name, alt, className = '', priority }: { name: 'battery' | 'inverter' | 'sodium' | 'cells'; alt: string; className?: string; priority?: boolean }) {
  return (
    <picture className="block h-full w-full">
      <source type="image/avif" srcSet={`/renders/${name}-800.avif 800w, /renders/${name}-1200.avif 1200w`} sizes="(min-width: 1024px) 50vw, 100vw" />
      {/* eslint-disable-next-line @next/next/no-img-element */}
      <img
        src={`/renders/${name}-1200.webp`}
        srcSet={`/renders/${name}-800.webp 800w, /renders/${name}-1200.webp 1200w`}
        sizes="(min-width: 1024px) 50vw, 100vw"
        alt={alt}
        width={1200}
        height={1200}
        loading={priority ? 'eager' : 'lazy'}
        fetchPriority={priority ? 'high' : 'auto'}
        decoding="async"
        className={`h-full w-full object-contain ${className}`}
      />
    </picture>
  );
}
